slug: partial-update-before-throw-corrupts-state
stack: dotnet
topic: exceptions
level: senior
type: find-bug
grading: auto
tags: [exception-design, exception-safety, state-consistency, validation]
code:
  language: csharp
  harness: statements
  source: |
    var payer = new Account { Id = "A", Balance = 100 };
    var payee = new Account { Id = "B", Balance = 50, IsFrozen = true };

    try
    {
        Transfer(payer, payee, 30);
    }
    catch (InvalidOperationException ex)
    {
        Console.WriteLine($"Transfer failed: {ex.Message}");
    }

    Console.WriteLine($"Total: {payer.Balance + payee.Balance}");

    static void Transfer(Account debit, Account credit, int amount)
    {
        debit.Balance -= amount;
        EnsureCanReceive(credit);
        credit.Balance += amount;
    }

    static void EnsureCanReceive(Account account)
    {
        if (account.IsFrozen)
        {
            throw new InvalidOperationException($"Account {account.Id} is frozen");
        }
    }

    class Account
    {
        public string Id = "";
        public int Balance;
        public bool IsFrozen;
    }
bugLineSets: [[17], [17, 18]]
fixedSource: |
  var payer = new Account { Id = "A", Balance = 100 };
  var payee = new Account { Id = "B", Balance = 50, IsFrozen = true };

  try
  {
      Transfer(payer, payee, 30);
  }
  catch (InvalidOperationException ex)
  {
      Console.WriteLine($"Transfer failed: {ex.Message}");
  }

  Console.WriteLine($"Total: {payer.Balance + payee.Balance}");

  static void Transfer(Account debit, Account credit, int amount)
  {
      EnsureCanReceive(credit);
      debit.Balance -= amount;
      credit.Balance += amount;
  }

  static void EnsureCanReceive(Account account)
  {
      if (account.IsFrozen)
      {
          throw new InvalidOperationException($"Account {account.Id} is frozen");
      }
  }

  class Account
  {
      public string Id = "";
      public int Balance;
      public bool IsFrozen;
  }
fixedExpect: { kind: output, value: "Transfer failed: Account B is frozen\nTotal: 150" }
